package synth

import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

class Counter3220 {
    var current: Int by Delegates.observable(20) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
sealed class Outcome3221 {
    data class Success(val payload: String) : Outcome3221()
    data object Failure : Outcome3221()
}

fun describe3221(outcome: Outcome3221): String = when (outcome) {
    is Outcome3221.Success -> outcome.payload
    Outcome3221.Failure -> "failed"
}
